{
  "shots": [
    {
      "id": "s1",
      "beat": "A cook in an apron stands at a kitchen counter, looks up from the chopping board and says, 'You are earlier than I expected.' She turns back to the board and goes on slicing, the knife tapping steadily against the wood.",
      "directives": {
        "camera": "hold",
        "framing": "medium",
        "pace": "steady",
        "tail": "ongoing"
      }
    },
    {
      "id": "s2",
      "beat": "She sets the knife down, turns toward the window and looks out at the street, her weight settling onto one hip. The kitchen is quiet apart from the low hum of the refrigerator.",
      "directives": {
        "join": "continuous",
        "camera": "pan_follow",
        "framing": "medium",
        "pace": "steady",
        "tail": "settle"
      }
    }
  ]
}
